import java.io.*;
import java.util.*;

public class Main {
    static final long INF = Long.MAX_VALUE / 4;

    static class Edge {
        int to, time, cost;
        Edge(int to, int time, int cost) { this.to = to; this.time = time; this.cost = cost; }
    }

    static class State implements Comparable<State> {
        long time; int cost, node;
        State(long time, int cost, int node) { this.time = time; this.cost = cost; this.node = node; }
        public int compareTo(State o) {
            if (time != o.time) return Long.compare(time, o.time);
            if (cost != o.cost) return Integer.compare(cost, o.cost);
            return Integer.compare(node, o.node);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);
        st.nextToken(); int V = (int) st.nval;
        st.nextToken(); int N = (int) st.nval;
        st.nextToken(); int M = (int) st.nval;

        List<Edge>[] adj = new ArrayList[N + 1];
        for (int i = 0; i <= N; i++) adj[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            st.nextToken(); int a = (int) st.nval;
            st.nextToken(); int b = (int) st.nval;
            st.nextToken(); int t = (int) st.nval;
            st.nextToken(); int p = (int) st.nval;
            adj[a].add(new Edge(b, t, p));
            adj[b].add(new Edge(a, t, p));
        }

        st.nextToken(); int X = (int) st.nval;
        st.nextToken(); int Y = (int) st.nval;

        int C = V;
        long[][] dp = new long[C + 1][N + 1];
        for (int c = 0; c <= C; c++) Arrays.fill(dp[c], INF);
        dp[0][X] = 0;

        PriorityQueue<State> pq = new PriorityQueue<>();
        pq.add(new State(0, 0, X));

        long best = INF;
        boolean[][] settled = new boolean[C + 1][N + 1];

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (settled[cur.cost][cur.node]) continue;
            settled[cur.cost][cur.node] = true;
            if (cur.node == Y && cur.time < best) best = cur.time;
            if (cur.time > dp[cur.cost][cur.node]) continue;
            for (Edge e : adj[cur.node]) {
                int nc = cur.cost + e.cost;
                if (nc > C) continue;
                long nt = cur.time + e.time;
                if (nt < dp[nc][e.to]) {
                    dp[nc][e.to] = nt;
                    pq.add(new State(nt, nc, e.to));
                }
            }
        }

        System.out.println(best >= INF ? -1 : best);
    }
}
